xml.Script:
        Colors[ 0] := 'FFFFFF'; // clWhite
        Colors[ 1] := 'FFFF00'; // clYellow
        Colors[ 2] := '0000CC'; // clBlue
        Colors[ 3] := 'FF0000'; // clRed
        Colors[ 4] := '00AA00'; // clGreen
        Colors[ 5] := '800080'; // clViolett
        Colors[ 6] := 'FFFFAA'; // clCream
        Colors[ 7] := '0066CC'; // clLightBlue
        Colors[ 8] := 'FF6000'; // clOrange
        Colors[ 9] := '00FF00'; // clLightGreen
        Colors[10] := 'FF88CC'; // clLightViolett
        Colors[11] := '666666'; // clGray

        R := 0.7;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';

        D := R * 0.81;

         // Rotate p around normalized v
        procedure RotatePoint(Xp, Yp, Zp, Xv, Yv, Zv, Angle);
        begin
            ca := Cos(Angle);
            sa := Sin(Angle);
            c2 := 1 - ca;

            sum := sqrt(Xv^2+Yv^2+Zv^2);
            Xv := Xv/sum;
            Yv := Yv/sum;
            Zv := Zv/sum;

            px[i] := Xp * (Xv * c2 * Xv + ca) +
                     Yp * (Yv * c2 * Xv - sa * Zv) +
                     Zp * (Zv * c2 * Xv + sa * Yv);

            py[i] := Xp * (Xv * c2 * Yv + sa * Zv) +
                     Yp * (Yv * c2 * Yv + ca) +
                     Zp * (Zv * c2 * Yv - sa * Xv);

            pz[i] := Xp * (Xv * c2 * Zv - sa * Yv) +
                     Yp * (Yv * c2 * Zv + sa * Xv) +
                     Zp * (Zv * c2 * Zv + ca);

            Inc(i);
        end;

        i := 0;
        RotatePoint ( ex[10], ey[10], ez[10],  cx[0], cy[0], cz[0], 1*pi/10);
        RotatePoint ( ex[10], ey[10], ez[10],  cx[0], cy[0], cz[0], 3*pi/10);
        RotatePoint ( ex[10], ey[10], ez[10],  cx[0], cy[0], cz[0], 5*pi/10);
        RotatePoint ( ex[10], ey[10], ez[10],  cx[0], cy[0], cz[0], 7*pi/10);
        RotatePoint ( ex[10], ey[10], ez[10],  cx[0], cy[0], cz[0], 9*pi/10);

        RotatePoint ( ex[9], ey[9], ez[9],  cx[1], cy[1], cz[1], 1*pi/10);
        RotatePoint ( ex[9], ey[9], ez[9],  cx[1], cy[1], cz[1], 3*pi/10);
        RotatePoint ( ex[9], ey[9], ez[9],  cx[1], cy[1], cz[1], 5*pi/10);
        RotatePoint ( ex[9], ey[9], ez[9],  cx[1], cy[1], cz[1], 7*pi/10);
        RotatePoint ( ex[9], ey[9], ez[9],  cx[1], cy[1], cz[1], 9*pi/10);

        RotatePoint ( ex[8], ey[8], ez[8],  cx[2], cy[2], cz[2],-1*pi/10);
        RotatePoint ( ex[8], ey[8], ez[8],  cx[2], cy[2], cz[2],-3*pi/10);
        RotatePoint ( ex[8], ey[8], ez[8],  cx[2], cy[2], cz[2],-5*pi/10);
        RotatePoint ( ex[8], ey[8], ez[8],  cx[2], cy[2], cz[2],-7*pi/10);
        RotatePoint ( ex[8], ey[8], ez[8],  cx[2], cy[2], cz[2],-9*pi/10);

        RotatePoint ( ex[6], ey[6], ez[6],  cx[3], cy[3], cz[3], 1*pi/10);
        RotatePoint ( ex[6], ey[6], ez[6],  cx[3], cy[3], cz[3], 3*pi/10);
        RotatePoint ( ex[6], ey[6], ez[6],  cx[3], cy[3], cz[3], 5*pi/10);
        RotatePoint ( ex[6], ey[6], ez[6],  cx[3], cy[3], cz[3], 7*pi/10);
        RotatePoint ( ex[6], ey[6], ez[6],  cx[3], cy[3], cz[3], 9*pi/10);

        RotatePoint ( ex[7], ey[7], ez[7],  cx[4], cy[4], cz[4], 1*pi/10);
        RotatePoint ( ex[7], ey[7], ez[7],  cx[4], cy[4], cz[4], 3*pi/10);
        RotatePoint ( ex[7], ey[7], ez[7],  cx[4], cy[4], cz[4], 5*pi/10);
        RotatePoint ( ex[7], ey[7], ez[7],  cx[4], cy[4], cz[4], 7*pi/10);
        RotatePoint ( ex[7], ey[7], ez[7],  cx[4], cy[4], cz[4], 9*pi/10);

        RotatePoint ( ex[2], ey[2], ez[2],  cx[5], cy[5], cz[5], -1*pi/10);
        RotatePoint ( ex[2], ey[2], ez[2],  cx[5], cy[5], cz[5], -3*pi/10);
        RotatePoint ( ex[2], ey[2], ez[2],  cx[5], cy[5], cz[5], -5*pi/10);
        RotatePoint ( ex[2], ey[2], ez[2],  cx[5], cy[5], cz[5], -7*pi/10);
        RotatePoint ( ex[2], ey[2], ez[2],  cx[5], cy[5], cz[5], -9*pi/10);
